//! Complete source-only doc snippets: query names, code index, actual doc judge.
//! This DATA owns no discovery, semantic or EOF authority.
use crate::{captured_api_pages as fund,captured_generator_budget::Budget,captured_raw_file::Config,captured_reactive_reads::Failure,captured_allow_annotations::Operation,reactive_raw_policy_pages::RawPolicyPages,doc_snippets_policy as policy,lint::{AllowUse,Site}};
use std::{io,sync::Arc,collections::HashSet};
pub struct Data{pub output:fund::ApiData,pub blocks:Vec<policy::SummaryBlock>}
struct Phase{budget:Arc<Budget>,complete:bool}impl Drop for Phase{fn drop(&mut self){if !self.complete{self.budget.keep_failed_scratch()}}}
fn oom(b:&Budget)->Failure{b.deny();Failure::Operational(io::ErrorKind::OutOfMemory.into())}
fn selected(config:&Config,relative:&str)->bool{!config.policy_path_exempt("doc_snippets",policy::metadata().group,relative)}
pub fn collect(pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<Data,Failure>{
 fund::checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|_|oom(root))?,complete:false};let b=&phase.budget;let pending=(||{
 let mut queries=HashSet::new();
 if !pages.for_each(&mut|relative,views|{fund::checked(b,poll)?;if !selected(config,relative)||!policy::is_doc_path(relative){return Ok(true)}let file=views.source_file()?;if relative!=file.rel{return Err("doc query source relative path differs".into())}let local=views.allocation_budget(root);policy::queries_file_using(file,&mut queries,&mut Operation{budget:b,poll},&mut Operation{budget:local,poll})?;fund::checked(local,poll)?;Ok(true)})?{return Err("doc query source stopped before EOF".into())}
 let mut names=policy::empty_names();
 if !pages.for_each(&mut|relative,views|{fund::checked(b,poll)?;if !selected(config,relative)||!relative.starts_with("code/")||!relative.ends_with(".dm"){return Ok(true)}let file=views.source_file()?;if relative!=file.rel{return Err("doc code index relative path differs".into())}let local=views.allocation_budget(root);views.clean(root)?;policy::names_file_using(file,&queries,&mut names,&mut Operation{budget:b,poll},&mut Operation{budget:local,poll})?;fund::checked(local,poll)?;Ok(true)})?{return Err("doc CODE index stopped before EOF".into())}
 let mut data=fund::empty();let mut summaries=Vec::new();let mut batches=Vec::new();
 if !pages.for_each(&mut|relative,views|{fund::checked(b,poll)?;if !selected(config,relative)||!policy::is_doc_path(relative){return Ok(true)}let file=views.source_file()?;if relative!=file.rel{return Err("doc judge source relative path differs".into())}let local=views.allocation_budget(root);let(sites,blocks)=policy::judge_file_using(file,&names,&mut Operation{budget:b,poll},&mut Operation{budget:local,poll})?;
 for block in blocks{fund::row(root,poll,&mut summaries)?;summaries.push(policy::SummaryBlock{kind:fund::own(root,poll,&block.kind)?,rel:fund::own(root,poll,&block.rel)?,first:fund::own(root,poll,&block.first)?});}
 for line in sites{fund::checked(local,poll)?;if let Some(kept)=crate::allow::kept_using(file,line,"doc_snippets",&mut Operation{budget:local,poll})?{let line=u32::try_from(kept.line).map_err(|_|oom(root))?;let code=kept.code.unwrap_or_default();if !data.allow_used.iter().any(|u|u.rel==file.rel&&u.line==line&&u.name=="doc_snippets"&&u.code==code){fund::row(root,poll,&mut data.allow_used)?;data.allow_used.push(AllowUse{rel:fund::own(root,poll,&file.rel)?,line,name:fund::own(root,poll,"doc_snippets")?,code:fund::own(root,poll,&code)?});}if !data.digests.contains_key(file.rel.as_str()){fund::node(root)?;data.digests.insert(fund::own(root,poll,&file.rel)?,crate::captured_raw_file::source_allow_digest(file));}continue}
 fund::row(root,poll,&mut data.sites)?;fund::row(root,poll,&mut data.source_text)?;data.sites.push(Site{rule:fund::own(root,poll,"doc_unknown_name")?,rel:fund::own(root,poll,relative)?,line:u32::try_from(line).map_err(|_|oom(root))?,msg:String::new(),ident:String::new(),key:String::new()});let raw=file.raw().line(line);let max=raw.len().checked_mul(4).and_then(|n|n.checked_add(256)).ok_or_else(||oom(root))?;root.charge(max).map_err(|_|oom(root))?;let text=crate::util::normalize_ws(raw);if text.capacity()>max{return Err(oom(root))}data.source_text.push(text);}
 fund::checked(local,poll)?;fund::row(b,poll,&mut batches)?;batches.push((fund::own(b,poll,relative)?,std::mem::replace(&mut data,fund::empty()),std::mem::take(&mut summaries)));Ok(true)})?{return Err("doc Markdown judge stopped before EOF".into())}
 // The original selected Tree walk is lexical. Keep each file's call/ALLOW order.
 b.charge(batches.len().checked_mul(4*std::mem::size_of::<(String,fund::ApiData,Vec<policy::SummaryBlock>)>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;
 dm_analysis::checker_order::sort_policy_data(&mut batches,&mut|left,right|->Result<std::cmp::Ordering,Failure>{fund::checked(b,poll)?;Ok(left.0.cmp(&right.0))})?;
 for(_,output,blocks)in batches{fund::append(&mut data,output,root,poll)?;fund::reserve_append(root,poll,&mut summaries,blocks.len())?;summaries.extend(blocks);}
 fund::checked(root,poll)?;Ok(Data{output:data,blocks:summaries})})();if matches!(&pending,Err(Failure::Operational(_))){return pending}fund::checked(root,poll)?;phase.complete=pending.is_ok();drop(phase);pending
}
